    public static func videos(now: Date = Date()) -> [Video] {
        seeds.map { s in
            Video(id: vid(s.n), authorID: uid(s.author), caption: s.caption, musicTitle: s.music, mood: s.mood,
                  duration: s.duration, source: .bundled(s.file), thumbnail: .bundled(s.file + "_thumb"),
                  likesCount: s.likes, commentsCount: s.comments, savesCount: s.saves, sharesCount: s.shares,
                  viewsCount: s.views, createdAt: now.addingTimeInterval(-s.hoursAgo * 3600),
                  isDemo: true)
        }
    }

    public static func comments(now: Date = Date()) -> [Comment] {
        let texts: [(Int, Int, String)] = [
            (1, 2, "Вот это заряд с утра 🔥"), (1, 5, "Повторил — соседи в шоке 😂"), (1, 4, "Цвета 🤌"),
            (2, 3, "Залип на минуту, спасибо"), (2, 6, "Поставлю на фон перед сном"),
            (3, 2, "Как это сделано?!"), (4, 3, "Это я каждую пятницу"), (4, 6, "АХАХАХ"), (4, 2, "Отправила всем друзьям"),
            (5, 2, "Хочу в этот вечер"), (7, 4, "Палитра — космос"), (8, 1, "Залип, проиграл 🙃"), (10, 3, "Уютнее некуда")
        ]
        return texts.enumerated().map { i, t in
            Comment(id: UUID(uuidString: String(format: "20000000-0000-4000-8000-%012d", i + 1))!,
                    videoID: vid(t.0), authorID: uid(t.1), text: t.2,
                    createdAt: now.addingTimeInterval(-Double(i + 1) * 1800), likesCount: (i * 7) % 40)
        }
    }

